 function dealCard(o){var tone=o.severity==='critical'||o.severity==='high'?'risk':o.risks.length?'warn':'';return'<div class="pl3-deal '+tone+' '+(o.editable?'':'connected')+'" draggable="'+(o.editable?'true':'false')+'" ondragstart="_rp2PipelineDrag(event,\''+encodeURIComponent(o.key)+'\')" onclick="_rp2PipelineOpen(\''+encodeURIComponent(o.key)+'\')" data-pipe511="1" data-search="'+esc([o.company,o.title,o.products,o.forecast].join(' ').toLowerCase())+'"><div class="pl3-deal-company">'+esc(o.company)+'</div><div class="pl3-deal-title">'+esc(o.title)+'</div><div class="pl3-deal-value">'+money(o.amount)+'</div><div class="pl3-deal-weight">'+money(o.weighted)+' weighted · '+o.probability+'%</div><div class="pl3-deal-tags"><span class="pl3-tag '+(o.forecast==='At Risk'?'risk':o.forecast==='Commit'?'good':'')+'">'+esc(o.forecast)+'</span>'+(o.risks.length?'<span class="pl3-tag risk">'+o.risks.length+' risk</span>':'<span class="pl3-tag good">Clear</span>')+(o.expectedClose?'<span class="pl3-tag">'+fmt(o.expectedClose)+'</span>':'')+'</div><div class="pl3-deal-next"><strong>Next:</strong> '+esc(o.nextStep||'No next step')+(o.nextStepDate?' · '+fmt(o.nextStepDate):'')+'</div></div>'}
