 function list(g){var rows=filtered(g).slice().sort(function(a,b){return (a.closed?1:0)-(b.closed?1:0)||b.riskScore-a.riskScore||b.amount-a.amount});return section('Opportunity list','Search, filter, and inspect every deal','Open and closed opportunities remain company-linked. Imported rows stay read-only.')+filterbar(g)+(rows.length?'<div class="pl3-table-wrap"><table class="pl3-table"><thead><tr><th>Company / Opportunity</th><th>Stage</th><th>Forecast</th><th>Amount</th><th>Weighted</th><th>Probability</th><th>Expected close</th><th>Last activity</th><th>Next step</th><th>Risk</th><th>Source</th></tr></thead><tbody>'+rows.map(function(o){return'<tr><td><button class="pl3-link" onclick="_rp2PipelineOpen(\''+encodeURIComponent(o.key)+'\')"><strong>'+esc(o.company)+'</strong><br>'+esc(o.title)+'</button></td><td>'+esc(o.stage)+'</td><td>'+esc(o.forecast)+'</td><td><strong>'+money(o.amount)+'</strong></td><td>'+money(o.weighted)+'</td><td>'+o.probability+'%</td><td>'+fmt(o.expectedClose)+'</td><td>'+fmt(o.lastActivity)+'<br>'+o.daysSinceActivity+' days ago</td><td>'+esc(o.nextStep||'Missing')+'<br>'+fmt(o.nextStepDate)+'</td><td>'+(o.risks.length?'<span class="pl3-pill risk">'+o.risks.length+' signals</span>':'<span class="pl3-pill good">Clear</span>')+'</td><td>'+esc(o.sourceName)+'</td></tr>'}).join('')+'</tbody></table></div>':empty('No opportunities match the filters','Create an opportunity or adjust the current filters.'))}
 function forecastView(g){var projected=g.ctx.qtd.revenue+g.buckets.Commit.value+g.buckets['Best Case'].weighted+g.buckets.Pipeline.weighted;return section('Forecast and coverage','Keep completed revenue separate from open opportunity value','Official revenue comes from weekly scorecards. Pipeline values remain planning estimates until an order is completed and recorded.')+'<div class="pl3-grid-4"><div class="pl3-summary"><div class="pl3-summary-label">Official completed revenue</div><div class="pl3-summary-title">'+money(g.ctx.qtd.revenue)+'</div><div class="pl3-summary-copy">Selected-point QTD scorecard through '+esc(g.ctx.selected.label)+'.</div></div><div class="pl3-summary"><div class="pl3-summary-label">Open unweighted pipeline</div><div class="pl3-summary-title">'+money(g.pipeline)+'</div><div class="pl3-summary-copy">Full value of '+g.open.length+' open CRM opportunities.</div></div><div class="pl3-summary"><div class="pl3-summary-label">Open weighted pipeline</div><div class="pl3-summary-title">'+money(g.weighted)+'</div><div class="pl3-summary-copy">Probability-weighted planning value; not actual sales.</div></div><div class="pl3-summary"><div class="pl3-summary-label">Directional combined projection</div><div class="pl3-summary-title">'+money(projected)+'</div><div class="pl3-summary-copy">Completed revenue + commit value + weighted best case and pipeline.</div></div></div>'+section('Pipeline coverage','How much opportunity exists against the remaining goal','Coverage is a planning ratio. It does not imply the open opportunities will close.')+'<div class="pl3-grid-3"><div class="pl3-summary"><div class="pl3-summary-label">Remaining official goal</div><div class="pl3-summary-title">'+money(g.remaining)+'</div><div class="pl3-summary-copy">'+money(g.ctx.qtd.revenue)+' recorded against '+money(g.ctx.goal)+' quarter goal.</div></div><div class="pl3-summary"><div class="pl3-summary-label">Unweighted coverage</div><div class="pl3-summary-title">'+(g.remaining?(g.coverage.toFixed(1)+'×'):'Goal met')+'</div><div class="pl3-summary-copy">Open pipeline divided by remaining official goal.</div></div><div class="pl3-summary"><div class="pl3-summary-label">Weighted coverage</div><div class="pl3-summary-title">'+(g.remaining?(g.weightedCoverage.toFixed(1)+'×'):'Goal met')+'</div><div class="pl3-summary-copy">Probability-weighted pipeline divided by remaining goal.</div></div></div>'+section('Forecast category mix','Where confidence currently sits','Risk rules can move an opportunity into At Risk even when its stage is late.')+forecastCards(g)+section('Forecast chart','Completed revenue and planning categories','The chart visually separates actual scorecard revenue from open CRM values.')+'<div class="pl3-panel"><div class="pl3-chart"><canvas id="pl3-chart"></canvas></div></div>'}
